pub fn find_max_in_prefix(v: &[i32], end: usize) -> (i32, usize) {
    assert!(!v.is_empty(), "array must be non-empty");
    assert!(end < v.len(), "end must be within array bounds");

    let mut max_val = v[0];
    let mut max_idx = 0usize;

    for i in 1..=end {
        let x = v[i];
        if x > max_val {
            max_val = x;
            max_idx = i;
        }
    }

    (max_val, max_idx)
}

pub fn find_min_in_suffix(v: &[i32], start: usize) -> (i32, usize) {
    assert!(!v.is_empty(), "array must be non-empty");
    assert!(start < v.len(), "start must be within array bounds");

    let mut min_val = v[start];
    let mut min_idx = start;

    for i in (start + 1)..v.len() {
        let x = v[i];
        if x < min_val {
            min_val = x;
            min_idx = i;
        }
    }

    (min_val, min_idx)
}

pub fn barrier(v: &[i32], p: usize) -> bool {
    assert!(!v.is_empty(), "array must be non-empty");
    assert!(p < v.len(), "p must be within array bounds");

    // Vacuously true: no elements to the right of p.
    if p + 1 == v.len() {
        return true;
    }

    let (max_left, _) = find_max_in_prefix(v, p);
    let (min_right, _) = find_min_in_suffix(v, p + 1);

    max_left < min_right
}

